export function SignupForm({ values = {}, errors = {} }) {
  const entries = Object.entries(errors);
  return (
    <form className="signup" noValidate>
      {entries.length > 0 ? (
        <div className="summary" role="alert">
          <p>{entries.length} problem{entries.length === 1 ? '' : 's'}</p>
          <ul>
            {entries.map(([name, message]) => (
              <li key={name}>
                <a href={`#${name}`}>{message}</a>
              </li>
            ))}
          </ul>
        </div>
      ) : null}
      <Field name="email" label="Email" type="email" value={values.email} error={errors.email} />
      <Field name="password" label="Password" type="password" value={values.password} error={errors.password} />
      <button type="submit">Create account</button>
    </form>
  );
}
```

